#include <iostream>
int main() {
    int count{7};
    const long long price_cents{125};
    long long total{count * price_cents};
    double ratio{7.0 / 2.0};
    char grade{'A'};
    bool affordable{total <= 1000};
    std::cout << total << ' ' << ratio << ' ' << grade << ' ' << affordable << '\n';
    return 0;
}

#include <iomanip>
#include <iostream>
int main() {
    int total{7};
    int count{2};
    double average{static_cast<double>(total) / count};
    long long square{70000LL * 70000LL};
    std::cout << total / count << ' ' << -7 / 3 << ' ' << -7 % 3 << '\n';
    std::cout << std::fixed << std::setprecision(2) << average << '\n';
    std::cout << square << '\n';
    return 0;
}

#include <iostream>
int main() {
    long long seconds{0};
    if (!(std::cin >> seconds) || seconds < 0 || seconds > 86400) {
        std::cerr << "INVALID\n";
        return 1;
    }
    std::cout << seconds / 3600 << ' ' << seconds % 3600 / 60
              << ' ' << seconds % 60 << '\n';
    return 0;
}

#include <iostream>
int main() {
    int n{0};
    if (!(std::cin >> n) || n < 0 || n > 1000) {
        std::cerr << "INVALID\n";
        return 1;
    }
    long long sum{0};
    int positive{0};
    for (int i{0}; i < n; ++i) {
        int value{0};
        if (!(std::cin >> value) || value < -1000 || value > 1000) {
            std::cerr << "INVALID\n";
            return 1;
        }
        sum += value;
        if (value > 0) {
            ++positive;
        }
    }
    std::cout << sum << ' ' << positive << '\n';
    return 0;
}

#include <iostream>
int main() {
    long long items{0};
    long long capacity{0};
    if (!(std::cin >> items >> capacity) || items < 0 || items > 1000000
        || capacity < 1 || capacity > 1000) {
        std::cerr << "INVALID\n";
        return 1;
    }
    long long full{items / capacity};
    long long remaining{items % capacity};
    long long boxes{full};
    if (remaining != 0) {
        ++boxes;
    }
    std::cout << full << ' ' << remaining << ' ' << boxes << '\n';
    return 0;
}

#include <iomanip>
#include <iostream>
int main() {
    int n{0};
    if (!(std::cin >> n) || n < 0 || n > 1000) {
        std::cerr << "INVALID\n";
        return 1;
    }
    long long sum{0};
    int i{0};
    while (i < n) {
        int value{0};
        if (!(std::cin >> value) || value < -1000 || value > 1000) {
            std::cerr << "INVALID\n";
            return 1;
        }
        sum += value;
        ++i;
    }
    if (n == 0) {
        std::cout << "EMPTY\n";
    } else {
        std::cout << std::fixed << std::setprecision(2)
                  << static_cast<double>(sum) / n << '\n';
    }
    return 0;
}
